code.cpp:
class Solution {
    int lps[105];
    int pattern[105];
    int trans[105][101];
    int m;

    void build(ListNode* head) {
        m = 0;
        while (head) {
            pattern[m++] = head->val;
            head = head->next;
        }
        lps[0] = 0;
        int len = 0, i = 1;
        while (i < m) {
            if (pattern[i] == pattern[len]) {
                lps[i++] = ++len;
            } else if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }
        for (int s = 0; s <= m; s++) {
            for (int v = 1; v <= 100; v++) {
                if (s < m && pattern[s] == v) {
                    trans[s][v] = s + 1;
                } else if (s == 0) {
                    trans[s][v] = 0;
                } else {
                    trans[s][v] = trans[lps[s - 1]][v];
                }
            }
        }
    }

    bool dfs(TreeNode* node, int state) {
        if (state == m) return true;
        if (!node) return false;
        int s = trans[state][node->val];
        if (s == m) return true;
        return dfs(node->left, s) || dfs(node->right, s);
    }

public:
    bool isSubPath(ListNode* head, TreeNode* root) {
        build(head);
        return dfs(root, 0);
    }
};
